var o=[{title:`Muchas causas, muchas respuestas`,text:`Las personas sienten molestias de espalda por motivos distintos, e incluso síntomas parecidos pueden tener causas diferentes. Algunas personas toleran bien la flexión, mientras que otras prefieren un tronco más neutro. El mejor ejercicio para ti depende de tus síntomas, tu capacidad, tu experiencia y cualquier consejo de tu profesional sanitario.`},{title:`Gestionar las exigencias`,text:`Practica tensar el tronco sin contener la respiración demasiado tiempo, aprende una bisagra controlada con un peso ligero y prueba ejercicios con apoyo o en el suelo cuando te convengan. Un bird dog suave o un dead bug entrenan el control del tronco sin pesos pesados. Ninguna postura única garantiza la seguridad, y mantener una «columna neutra» no significa bloquear todos los movimientos normales de la columna.`},{title:`Progresar con el tiempo`,text:`Si te resulta cómodo, haz el entrenamiento más difícil poco a poco añadiendo repeticiones, rango o carga. Toma notas de cómo se siente tu espalda durante y después de las sesiones. Si los síntomas empeoran, haz las cosas más fáciles. Si el dolor persiste, busca consejo profesional; las elecciones de ejercicio de una app no pueden sustituirlo.`},{title:`Señales urgentes`,text:`Los cambios nuevos en la vejiga o el intestino, el entumecimiento alrededor de la ingle, una debilidad grave o creciente en las piernas o el dolor de espalda tras una lesión importante necesitan una valoración médica urgente.`},{title:`Cómo usar TrainUp`,text:`Añade tu zona lumbar como limitación en Perfil, con una nota, para que el plan elija ejercicios adecuados. Después de cada entrenamiento puedes añadir notas e indicar dolor con la zona del cuerpo y el ejercicio. Si un ejercicio provoca dolor, «Siento dolor» lo termina y lo mantiene fuera de tus planes hasta que lo reactives desde Perfil. TrainUp no diagnostica la causa del dolor de espalda.`}];var n=[{label:`NHS: dolor de espalda y señales de alarma urgentes`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:o,sources:n};export{s as default,o as sections,n as sources};